/* ПЯТЬ В РЯД (гомоку) на клетках листа: поле 15×15 с B3.
   Против компьютера (два уровня), вдвоём за одним компьютером — или вдвоём через общую книгу:
   книга в режиме совместной работы, у каждого открыт этот плагин; ход — значок в клетке,
   он приходит коллеге правкой книги, и его плагин принимает ход. Поэтому состояние партии
   всегда можно прочитать с самого листа. */

/* ===== Поле на клетках листа: общий кусок игр магазина =====
   Строки и столбцы здесь — С НУЛЯ (r, c); адреса A1 считаются отсюда же.
   ячейка(строка, столбец) API плагина считает с единицы — поэтому везде «+ 1». */
const БУКВА = c => { let s = '', n = c + 1; while(n > 0){ const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = (n - 1 - m) / 26; } return s; };
const АДРЕС = (r, c) => БУКВА(c) + (r + 1);
const ОБЛАСТЬ = (r1, c1, r2, c2) => АДРЕС(r1, c1) + ':' + АДРЕС(r2, c2);
const клетка = (r, c) => ячейка(r + 1, c + 1);
/* Квадратные клетки: ширина столбца в знаках (знак — 7 точек), высота строки в пунктах (×4/3 точки). */
function клеткиКвадратом(r1, c1, r2, c2, точек){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(точек / 7);
  о.SetRowHeight(точек * 0.75);
}
/* Вернуть области обычные размеры клеток (столбец 92 точки, строка 24 точки = 18 пунктов). */
function обычныеРазмеры(r1, c1, r2, c2){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(92 / 7);
  о.SetRowHeight(18);
}
/* Ширина одного столбца и высота одной строки в точках экрана. */
function ширинаСтолбца(c, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c, 0, c)).SetColumnWidth(точек / 7); }
function высотаСтроки(r, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r, 0, r, 0)).SetRowHeight(точек * 0.75); }
/* Приложение запоминает смещения строк и не сбрасывает их, когда плагин меняет высоты строк:
   после этого щелчок мыши попадает не в ту клетку. Пустая запись в далёкую пустую строку
   растит сетку листа, и смещения пересчитываются. Звать после смены высот. */
async function обновитьВысоты(){
  /* каждый раз — строка дальше прежней: сетка растёт, только если запись за её краем */
  let n = 0; try { n = +лист().память('высоты-шаг') || 0; } catch(e){}
  for(let k = n + 1; k <= n + 40; k++){
    const r = 5999 + k;
    let v = null;
    try { v = await клетка(r, 0).прочитать(); } catch(e){ continue; }
    if(v === null || v === undefined || v === ''){
      клетка(r, 0).значение = null;
      try { лист().запомнить('высоты-шаг', k); } catch(e){}
      return true;
    }
  }
  return false;
}
/* Курсор — на «стоянку» рядом с полем. Тогда повторный щелчок по той же клетке
   снова сменит выделение, и плагин получит событие: иначе второй щелчок молчал бы. */
function наСтоянку(r, c){ клетка(r, c).выделить(); }
/* Пуста ли область листа: игра не должна молча затирать чужие данные. */
async function областьПуста(r1, c1, r2, c2){
  const строки = await диапазон(ОБЛАСТЬ(r1, c1, r2, c2)).прочитать();
  for(const ряд of строки || []) for(const v of ряд || []) if(v !== null && v !== undefined && v !== '') return false;
  return true;
}
/* Рамка: все четыре стороны одним видом. */
const РАМКА = (вид, цвет) => ({в: {вид, цвет}, н: {вид, цвет}, л: {вид, цвет}, п: {вид, цвет}});
/* Число со словом в нужной форме: число(5, 'выстрел', 'выстрела', 'выстрелов') → «5 выстрелов». */
function число(n, одна, две, пять){ const a = Math.abs(n) % 100, b = a % 10;
  return n + ' ' + (a > 10 && a < 20 ? пять : b === 1 ? одна : b >= 2 && b <= 4 ? две : пять); }
/* Время «м:сс». */
const ВРЕМЯ = с => Math.floor(с / 60) + ':' + String(Math.floor(с % 60)).padStart(2, '0');
/* Повод события — клетка с нуля и на нужном ли листе. */
function гдеЩелчок(п, лист){
  if(!п || !п.адрес || (лист && п.лист !== лист)) return null;
  if(п.клеток > 1) return null;                     /* протянули мышью область — это не ход */
  return {r: п.строка - 1, c: п.столбец - 1};
}
/* Защита от «правой кнопки»: правый щелчок сначала зовёт меню, а через 150 мс
   приходит выделение той же клетки. Такой выбор ходом не считаем. */
let последнееМеню = {адрес: '', t: 0};
const этоПослеМеню = п => п && п.адрес === последнееМеню.адрес && Date.now() - последнееМеню.t < 1500;
/* ===== конец общего куска ===== */
/* Оформление области по клеткам. Api GetRange(…).SetNumberFormat и другие оформления области из потока
   задевают только ту часть, что была занята при запуске потока, — свежие строки остаются без оформления.
   л — лист плагина: лист(имя) или черновик; строки и столбцы — с нуля. */
function оформитьОбласть(л, r1, c1, r2, c2, стиль){
  if((r2 - r1 + 1) * (c2 - c1 + 1) > 300000) return false;
  for(let r = r1; r <= r2; r++) for(let c = c1; c <= c2; c++) л.ячейка(r + 1, c + 1).стиль = стиль;
  return true;
}

const Р0 = 2, С0 = 1, N = 15, СТОЯНКА = {r: 1, c: 0};
const ПАМЯТЬ = 'пять-в-ряд';
const Х = '✕', О = '○';
const ЦВЕТ = {[Х]: '#296DF4', [О]: '#e5484d'};
const РЕЖИМЫ = ['против компьютера — я хожу первым', 'против компьютера — компьютер начинает', 'вдвоём за одним компьютером',
  'вдвоём через общую книгу — я играю ✕', 'вдвоём через общую книгу — я играю ○'];

let игра = null;   /* {лист, режим, уровень, поле[225] ('', ✕, ○), ходы[], конец, линия[]} */

const кто = () => игра.ходы.length % 2 ? О : Х;         /* ✕ всегда начинает */
const сеть = () => игра.режим.startsWith('вдвоём через');
const мойЗнак = () => сеть() ? (игра.режим.endsWith('✕') ? Х : О) : игра.режим.endsWith('начинает') ? О : Х;
const противКомпьютера = () => игра.режим.startsWith('против');
function сохранить(){ лист(игра.лист).запомнить(ПАМЯТЬ, игра); }

/* --- рисование ------------------------------------------------------------ */
const РАМКА_ПОЛЯ = (r, c) => ({в: {вид: r === 0 ? 'средняя' : 'тонкая', цвет: r === 0 ? '#151c2e' : '#c5ccd8'},
  н: {вид: r === N - 1 ? 'средняя' : 'тонкая', цвет: r === N - 1 ? '#151c2e' : '#c5ccd8'},
  л: {вид: c === 0 ? 'средняя' : 'тонкая', цвет: c === 0 ? '#151c2e' : '#c5ccd8'},
  п: {вид: c === N - 1 ? 'средняя' : 'тонкая', цвет: c === N - 1 ? '#151c2e' : '#c5ccd8'}});
function рисоватьКлетку(i, сРамкой){
  const r = Math.floor(i / N), c = i % N, к = клетка(Р0 + r, С0 + c), v = игра.поле[i];
  const последний = игра.ходы.length && игра.ходы[игра.ходы.length - 1] === i, вЛинии = (игра.линия || []).includes(i);
  к.значение = v;
  const ст = {align: 'center', valign: 'middle', b: 1, size: 15, color: v ? ЦВЕТ[v] : null,
    fill: вЛинии ? '#c9f2d4' : последний ? '#fff3bf' : null};
  if(сРамкой) ст.гр = РАМКА_ПОЛЯ(r, c);
  к.стиль = ст;
}
function шапка(){
  const к = клетка(0, С0);
  let t = 'Пять в ряд · ' + игра.режим;
  if(игра.конец === 'ничья') t += ' · НИЧЬЯ';
  else if(игра.конец) t += ' · ПОБЕДИЛ ' + игра.конец + (противКомпьютера() ? (игра.конец === мойЗнак() ? ' (вы)' : ' (компьютер)') : '');
  else t += ' · ходит ' + кто() + (сеть() ? (кто() === мойЗнак() ? ' (вы)' : ' (коллега)') : '');
  к.значение = t;
  к.стиль = {b: 1, size: 12, color: игра.конец ? '#15803d' : '#151c2e'};
}
function нарисоватьВсё(сРамкой){ for(let i = 0; i < N * N; i++) рисоватьКлетку(i, сРамкой); шапка(); }
function показатьСчёт(){
  if(!игра){ панель.список('сейчас', [['Партия', 'не начата — выберите режим и нажмите «Новая партия»']]); return; }
  панель.список('сейчас', [['Режим', игра.режим], ['Ходов', String(игра.ходы.length)],
    ['Ходит', игра.конец ? '—' : кто() + (противКомпьютера() ? (кто() === мойЗнак() ? ' — вы' : ' — компьютер') : сеть() ? (кто() === мойЗнак() ? ' — вы' : ' — коллега') : '')],
    ['Итог', игра.конец === 'ничья' ? 'ничья' : игра.конец ? 'победил ' + игра.конец : 'идёт']]);
}
function показатьСтатистику(){
  const с = хранилище.взять('счёт', {}) || {};
  панель.список('счёт', ['обычный', 'сильный'].map(у => { const x = с[у] || {}; return ['Компьютер, ' + у, 'побед: ' + (x.победы || 0) + ' · поражений: ' + (x.поражения || 0) + ' · ничьих: ' + (x.ничьи || 0)]; }));
}

/* --- правила ---------------------------------------------------------------- */
const НАПРАВЛЕНИЯ = [[0, 1], [1, 0], [1, 1], [1, -1]];
function линияПобеды(поле, i){
  const v = поле[i], r = Math.floor(i / N), c = i % N;
  if(!v) return null;
  for(const [dr, dc] of НАПРАВЛЕНИЯ){
    const линия = [i];
    for(const s of [1, -1]){ let rr = r + dr * s, cc = c + dc * s;
      while(rr >= 0 && cc >= 0 && rr < N && cc < N && поле[rr * N + cc] === v){ линия.push(rr * N + cc); rr += dr * s; cc += dc * s; } }
    if(линия.length >= 5) return линия;
  }
  return null;
}

/* --- компьютер ----------------------------------------------------------------
   Оценка клетки — по всем «окнам» из пяти клеток через неё: окно без чужих камней
   тем ценнее, чем больше в нём своих (1, 10, 100, 1000, победа). Атака и защита
   считаются одинаково — за себя и за соперника. Сильный уровень вдобавок смотрит
   ответ соперника на каждый из лучших ходов. */
const ВЕС = [0, 2, 24, 300, 6000, 1000000];
function оценкаКлетки(поле, i, я){
  const r = Math.floor(i / N), c = i % N, он = я === Х ? О : Х;
  let за = 0, против = 0;
  for(const [dr, dc] of НАПРАВЛЕНИЯ){
    for(let k = -4; k <= 0; k++){
      let мои = 0, его = 0, внутри = true;
      for(let s = 0; s < 5; s++){
        const rr = r + dr * (k + s), cc = c + dc * (k + s);
        if(rr < 0 || cc < 0 || rr >= N || cc >= N){ внутри = false; break; }
        const v = поле[rr * N + cc];
        if(v === я) мои++; else if(v === он) его++;
      }
      if(!внутри) continue;
      if(!его) за += ВЕС[мои + 1];
      if(!мои) против += ВЕС[его + 1];
    }
  }
  return за + против * 0.9;
}
function кандидаты(поле){
  const out = [];
  if(поле.every(x => !x)) return [Math.floor(N / 2) * N + Math.floor(N / 2)];
  for(let i = 0; i < N * N; i++){
    if(поле[i]) continue;
    const r = Math.floor(i / N), c = i % N;
    let рядом = false;
    for(let dr = -2; dr <= 2 && !рядом; dr++) for(let dc = -2; dc <= 2; dc++){
      const rr = r + dr, cc = c + dc;
      if(rr >= 0 && cc >= 0 && rr < N && cc < N && поле[rr * N + cc]){ рядом = true; break; }
    }
    if(рядом) out.push(i);
  }
  return out;
}
function ходКомпьютера(){
  const поле = игра.поле, я = кто(), он = я === Х ? О : Х;
  const список = кандидаты(поле).map(i => ({i, о: оценкаКлетки(поле, i, я) + Math.random()})).sort((a, b) => b.о - a.о);
  if(!список.length) return null;
  /* свой выигрыш и чужой выигрыш — проверяем прямо */
  for(const x of список){ поле[x.i] = я; const w = линияПобеды(поле, x.i); поле[x.i] = ''; if(w) return x.i; }
  for(const x of список){ поле[x.i] = он; const w = линияПобеды(поле, x.i); поле[x.i] = ''; if(w) return x.i; }
  if(игра.уровень !== 'сильный') return список[0].i;
  /* сильный: для лучших ходов смотрим лучший ответ соперника */
  let лучший = список[0].i, итог = -Infinity;
  for(const x of список.slice(0, 10)){
    поле[x.i] = я;
    let ответ = 0;
    for(const j of кандидаты(поле)){ const о = оценкаКлетки(поле, j, он); if(о > ответ) ответ = о; }
    поле[x.i] = '';
    const сумма = x.о - ответ * 0.8;
    if(сумма > итог){ итог = сумма; лучший = x.i; }
  }
  return лучший;
}

/* --- ход ------------------------------------------------------------------ */
function поставить(i){
  const знак = кто();
  игра.поле[i] = знак;
  const прежний = игра.ходы.length ? игра.ходы[игра.ходы.length - 1] : null;
  игра.ходы.push(i);
  if(прежний !== null) рисоватьКлетку(прежний);
  const линия = линияПобеды(игра.поле, i);
  if(линия){ игра.конец = знак; игра.линия = линия; for(const j of линия) рисоватьКлетку(j); }
  else if(игра.ходы.length === N * N) игра.конец = 'ничья';
  рисоватьКлетку(i);
  if(игра.конец) итогПартии();
}
function итогПартии(){
  if(противКомпьютера()){
    const с = хранилище.взять('счёт', {}) || {}, у = игра.уровень || 'обычный';
    с[у] = с[у] || {};
    const поле = игра.конец === 'ничья' ? 'ничьи' : игра.конец === мойЗнак() ? 'победы' : 'поражения';
    с[у][поле] = (с[у][поле] || 0) + 1;
    хранилище.положить('счёт', с); показатьСтатистику();
    панель.сообщение(игра.конец === 'ничья' ? 'Ничья — поле кончилось.' : игра.конец === мойЗнак() ? 'Победа! Пять в ряд.' : 'Компьютер собрал пять в ряд. Ещё партию?');
  } else панель.сообщение(игра.конец === 'ничья' ? 'Ничья.' : 'Победил ' + игра.конец + '!');
}
function ответКомпьютера(){
  if(!игра.конец && противКомпьютера() && кто() !== мойЗнак()){
    const i = ходКомпьютера();
    if(i !== null) поставить(i);
  }
}
function клеткаПоля(п){
  if(!игра || !п || !п.адрес || п.лист !== игра.лист || п.клеток > 1) return null;
  const r = п.строка - 1 - Р0, c = п.столбец - 1 - С0;
  return r >= 0 && c >= 0 && r < N && c < N ? r * N + c : null;
}

/* --- обработчики ---------------------------------------------------------- */
function Старт(){
  показатьСтатистику();
  let м = null;
  try { м = лист().память(ПАМЯТЬ); } catch(e){}
  if(м && м.поле && !м.конец){
    игра = м;
    панель.сообщение('Незаконченная партия на этом листе — продолжаем.');
  }
  показатьСчёт();
}
async function НоваяПартия(){
  const п = параметры({});
  const имяЛиста = книга.выделение ? книга.выделение.лист : книга.листы[0];
  let своё = null;
  try { своё = лист().память(ПАМЯТЬ); } catch(e){}
  if(!своё && !(await областьПуста(0, С0, Р0 + N - 1, С0 + N - 1))){
    if(!(await диалог.вопрос('На этом листе в B1:P17 уже что-то есть. Поле ляжет поверх. Лучше завести для игры пустой лист (+ внизу). Всё равно положить здесь?'))) return;
  }
  игра = {лист: имяЛиста, режим: п.режим || РЕЖИМЫ[0], уровень: п.уровень || 'обычный', поле: new Array(N * N).fill(''), ходы: [], конец: null, линия: []};
  клеткиКвадратом(Р0, С0, Р0 + N - 1, С0 + N - 1, 28);
  await обновитьВысоты();
  нарисоватьВсё(true);
  ответКомпьютера();
  шапка(); сохранить(); показатьСчёт();
  наСтоянку(СТОЯНКА.r, СТОЯНКА.c);
  панель.сообщение(сеть() ? 'Новая партия. Коллега открывает эту же книгу в совместной работе, выбирает другой знак и нажимает «Присоединиться». ✕ ходит первым.'
    : 'Новая партия. Щёлкните клетку, чтобы поставить ' + (противКомпьютера() ? мойЗнак() : Х) + '. Цель — пять в ряд по горизонтали, вертикали или диагонали.');
}
/* Партия по общей книге уже идёт: читаем поле с листа. */
async function Присоединиться(){
  const п = параметры({});
  const имяЛиста = книга.выделение ? книга.выделение.лист : книга.листы[0];
  const строки = await диапазон(ОБЛАСТЬ(Р0, С0, Р0 + N - 1, С0 + N - 1)).прочитать();
  игра = {лист: имяЛиста, режим: п.режим || РЕЖИМЫ[3], уровень: 'обычный', поле: new Array(N * N).fill(''), ходы: [], конец: null, линия: []};
  прочестьПоле(строки);
  нарисоватьВсё(true); сохранить(); показатьСчёт();
  панель.сообщение('Партия с листа: на поле ' + игра.ходы.length + ' ходов, ходит ' + кто() + (кто() === мойЗнак() ? ' — вы.' : ' — коллега.'));
}
/* Поле, прочитанное с листа → состояние. Порядок ходов с листа не восстановить, важны только камни и чей ход. */
function прочестьПоле(строки){
  const поле = new Array(N * N).fill(''), ходы = [];
  for(let r = 0; r < N; r++) for(let c = 0; c < N; c++){
    const v = String((строки[r] || [])[c] == null ? '' : строки[r][c]).trim().toLowerCase();
    const знак = v === Х || v === 'x' || v === 'х' ? Х : v === О || v === 'o' || v === 'о' || v === '0' ? О : '';
    if(знак){ поле[r * N + c] = знак; ходы.push(r * N + c); }
  }
  игра.поле = поле;
  /* в ходах — сначала ✕, потом ○ попеременно: так «кто ходит» считается по количеству */
  const хи = ходы.filter(i => поле[i] === Х), ои = ходы.filter(i => поле[i] === О), по = [];
